		velocity.y += GRAVITY * delta
	else:
		velocity.y = 0.0
	move_and_slide()

extends Label

var score: int = 0


func _ready() -> void:
	_update_text()


func add(points: int) -> void:
	score += points
	_update_text()


func _update_text() -> void:
	text = "Score: %d" % score

extends RefCounted


static func save_data(data: Dictionary, path: String) -> void:
	var file := FileAccess.open(path, FileAccess.WRITE)
	if file == null:
		push_error("save_data: cannot open '%s' for writing (error %d)" % [path, FileAccess.get_open_error()])
		return
	file.store_string(JSON.stringify(data))
	file.close()


static func load_data(path: String) -> Dictionary:
	if not FileAccess.file_exists(path):
		return {}
	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		push_error("load_data: cannot open '%s' for reading (error %d)" % [path, FileAccess.get_open_error()])
		return {}
	var text := file.get_as_text()
	file.close()
	var parsed: Variant = JSON.parse_string(text)
	if parsed is Dictionary:
		return parsed
	return {}

extends Node

enum State { CLOSED, OPENING, OPEN }

const OPEN_DURATION := 0.5

var _state: State = State.CLOSED
var _elapsed := 0.0


func interact() -> void:
	if _state == State.CLOSED:
		_state = State.OPENING
		_elapsed = 0.0


func get_state_name() -> String:
	match _state:
		State.OPENING:
			return "OPENING"
		State.OPEN:
			return "OPEN"
	return "CLOSED"


func _process(delta: float) -> void:
	if _state == State.OPENING:
		_elapsed += delta
		if _elapsed >= OPEN_DURATION:
			_state = State.OPEN

extends RefCounted

var _items: Dictionary = {}


func add_item(item_name: String, count: int) -> void:
	if count <= 0:
		return
	_items[item_name] = get_count(item_name) + count


func remove_item(item_name: String, count: int) -> bool:
	if count < 0 or get_count(item_name) < count:
		return false
	var remaining: int = get_count(item_name) - count
	if remaining == 0:
		_items.erase(item_name)
	else:
		_items[item_name] = remaining
	return true


func get_count(item_name: String) -> int:
	return _items.get(item_name, 0)

extends Node


func load_level(path: String) -> Node:
	var scene := load(path) as PackedScene
	if scene == null:
		push_error("Could not load level scene: %s" % path)
		return null
	var level := scene.instantiate()
	add_child(level)
	return level

