extends Node2D


func first_hit(from: Vector2, to: Vector2) -> Vector2:
	var space_state := get_world_2d().direct_space_state
	var query := PhysicsRayQueryParameters2D.create(from, to)
	var result := space_state.intersect_ray(query)
	if result.is_empty():
		return to
	return result.position

extends RefCounted


func find_path(size: Vector2i, walls: Array[Vector2i], from: Vector2i, to: Vector2i) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	if not _in_bounds(size, from) or not _in_bounds(size, to):
		return result

	var blocked := {}
	for w in walls:
		blocked[w] = true
	if blocked.has(from) or blocked.has(to):
		return result

	var came_from := {from: from}
	var queue: Array[Vector2i] = [from]
	var head := 0
	var dirs: Array[Vector2i] = [Vector2i.UP, Vector2i.DOWN, Vector2i.LEFT, Vector2i.RIGHT]

	while head < queue.size():
		var current: Vector2i = queue[head]
		head += 1
		if current == to:
			break
		for d in dirs:
			var next: Vector2i = current + d
			if not _in_bounds(size, next) or blocked.has(next) or came_from.has(next):
				continue
			came_from[next] = current
			queue.append(next)

	if not came_from.has(to):
		return result

	var cell := to
	result.append(cell)
	while cell != from:
		cell = came_from[cell]
		result.append(cell)
	result.reverse()
	return result


func _in_bounds(size: Vector2i, cell: Vector2i) -> bool:
	return cell.x >= 0 and cell.y >= 0 and cell.x < size.x and cell.y < size.y

