class _Waiter extends RefCounted:
	signal finished(result: bool)
	var done := false

	func on_signal() -> void:
		_finish(true)

	func on_timeout() -> void:
		_finish(false)

	func _finish(result: bool) -> void:
		if done:
			return
		done = true
		finished.emit(result)


## Waits until `sig` is emitted or `seconds` of game time pass, whichever comes first.
## Returns true if the signal came first, false on timeout.
func wait_for(sig: Signal, seconds: float) -> bool:
	var waiter := _Waiter.new()
	var timer := get_tree().create_timer(seconds)
	sig.connect(waiter.on_signal)
	timer.timeout.connect(waiter.on_timeout)

	var result: bool = await waiter.finished

	if sig.is_connected(waiter.on_signal):
		sig.disconnect(waiter.on_signal)
	if timer.timeout.is_connected(waiter.on_timeout):
		timer.timeout.disconnect(waiter.on_timeout)
	return result
